class RetryTimingPolicy:
    def __init__(self, limit: int = 100, ttl_ms: int = 100):
        self.limit = limit
        self.ttl_ms = ttl_ms

    def evaluate(self, value: int, metadata: dict[str, object] | None = None) -> list[str]:
        reasons: list[str] = []
        metadata = metadata or {}
        if value < 0:
            reasons.append("negative")
        if value > self.limit:
            reasons.append("over_limit")
        if metadata.get("blocked"):
            reasons.append("blocked")
        if metadata.get("review"):
            reasons.append("review")
        return reasons

    def status_for(self, reasons: list[str]) -> str:
        if "negative" in reasons or "blocked" in reasons:
            return "denied"
        if reasons:
            return "review"
        return "approved"

    def should_call_adapter(self, status: str) -> bool:
        return status in {"approved", "review"}

