from retry_timing_models import RetryTimingRecord
from retry_timing_repository import RetryTimingRepository
from retry_timing_policy import RetryTimingPolicy
from retry_timing_service import RetryTimingService

def setup_service():
    repo=RetryTimingRepository([RetryTimingRecord("r1", "none"), RetryTimingRecord("r2", "none")])
    audit=AuditTrail() if "AuditTrail" in globals() else None
    adapter=ExternalAdapter() if "ExternalAdapter" in globals() else None
    clock=ManualClock(0) if "ManualClock" in globals() else None
    return repo, audit, adapter, RetryTimingService(repo, RetryTimingPolicy(limit=100), audit, adapter, clock)

def test_first_acquire_returns_token():
    _,_,_,s=setup_service(); assert s.acquire_retry_timing("r1","w1")["token"] == 1

def test_second_acquire_returns_newer_token():
    _,_,_,s=setup_service(); a=s.acquire_retry_timing("r1","w1"); b=s.acquire_retry_timing("r1","w2"); assert b["token"] > a["token"]

def test_stale_token_is_rejected():
    repo,_,_,s=setup_service(); a=s.acquire_retry_timing("r1","w1"); s.acquire_retry_timing("r1","w2"); assert s.apply_retry_timing("r1","w1",a["token"],10)["ok"] is False

def test_wrong_owner_is_rejected():
    _,_,_,s=setup_service(); a=s.acquire_retry_timing("r1","w1"); assert s.apply_retry_timing("r1","w2",a["token"],10)["ok"] is False

def test_approved_updates_value():
    repo,_,_,s=setup_service(); a=s.acquire_retry_timing("r1","w1"); s.apply_retry_timing("r1","w1",a["token"],10); assert repo.get("r1").value == 10
